def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([np.ones(n)] + [(st == l).astype(float) for l in labs[1:]])
    def ll(Z):
        A = np.column_stack([S, Z]) if Z is not None and len(Z) else S
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    def M(sel): return X[:, sel] if sel else np.zeros((n, 0))
    sel = []; base = ll(None)
    for k in range(MAX_DRIVERS):
        alpha = (0.25 if k == 0 else 0.1) / p
        best, bj = -1, None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            g = ll(M(sel + [j])) - base
            if g > best: best, bj = g, j
        if bj is None or stats.chi2.sf(2 * best, 1) > alpha: break
        clus = [m for m in range(p) if abs(R[bj, m]) >= 0.6 and m not in sel]
        if len(clus) > 1:
            lls = {m: ll(M(sel + [m])) for m in clus}
            top = max(lls.values())
            cand = [m for m in clus if lls[m] >= top - 2]
            def cost(c):
                l0 = lls[c]
                return sum(max(ll(M(sel + [c, m])) - l0, 0) for m in clus if m != c)
            bj = min(cand, key=cost)
        sel.append(bj); base = ll(M(sel))
    changed = True
    while changed and sel:
        changed = False; full = ll(M(sel))
        for s in list(sel):
            rest = [t for t in sel if t != s]
            if stats.chi2.sf(2 * (full - ll(M(rest))), 1) > 0.1 / p:
                sel.remove(s); changed = True; break
    base = ll(M(sel)); r0 = y - y.mean()
    sc = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            z = X[:, a] * X[:, b]; z = z - z.mean(); d = np.sqrt(np.sum(z * z))
            if d > 0: sc.append((abs(z @ r0) / d, a, b))
    sc.sort(reverse=True)
    npair = p * (p + 1) / 2; prods = []
    for _, a, b in sc[:15]:
        mains = sorted(set(sel) | {a, b})
        l1 = ll(M(mains)); z = (X[:, a] * X[:, b])[:, None]
        g = ll(np.column_stack([M(mains), z])) - l1
        pv = stats.chi2.sf(2 * g, 1)
        if pv < 0.01 / npair: prods.append((pv, a, b))
    prods.sort(); prods = prods[:2]
    drivers = [ids[s] for s in sel]
    for _, a, b in prods:
        for m in (a, b):
            if ids[m] not in drivers: drivers.append(ids[m])
    cols = sorted(set(sel) | {m for _, a, b in prods for m in (a, b)})
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[c] for c in cols),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

